package com.company.platform.aigateway.orchestration;import java.util.*;import org.springframework.stereotype.Component;@Component public class AICapabilityRegistry{private final Map<UUID,Map<String,Object>> values=new HashMap<>();public Map<String,Object> register(UUID tenant,String name,String version){UUID id=UUID.randomUUID();Map<String,Object>x=Map.of("id",id,"tenantId",tenant,"name",name,"version",version,"enabled",false);values.put(id,x);return x;}public List<Map<String,Object>> list(UUID tenant){return values.values().stream().filter(x->tenant.equals(x.get("tenantId"))).toList();}}
